const sourceMetadata = { source: "MidiFlow curated knowledge base", sourceType: "curated", licenseStatus: "metadata_only" };
const song = (artistId: string, title: string, releaseYear: number, genre: string, subgenre: string, features: string[]): JamaicanSongMetadata => ({
  songId: `${artistId}-${title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`,
  artistId,
  title,
  releaseYear,
  genre,
  subgenre,
  bpm: null,
  key: null,
  mode: null,
  durationSeconds: null,
  instrumentation: [],
  musicalFeatures: features,
  source: sourceMetadata.source,
  sourceType: "curated_metadata",
  sourceUrl: null,
  licenseStatus: "metadata_only",
  confidence: 0.72,
  status: "pending",
  lastVerified: null,
});

const artist = (input: Omit<JamaicanArtistProfile, "sourceMetadata" | "instruments" | "confidenceScore" | "status" | "lastVerified">): JamaicanArtistProfile => ({
  ...input,
  instruments: Object.fromEntries(input.instrumentPreferences.map((instrument, index) => [instrument, Number(Math.max(0.45, 1 - index * 0.12).toFixed(2))])),
  confidenceScore: 0.72,
  sourceMetadata,
  status: "pending",
  lastVerified: null,
});

