function normalize(value: string) { return value.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim(); }
function unique(values: string[]) { return [...new Set(values.filter(Boolean))]; }

export function detectJamaicanArtists(prompt: string) {
  const text = normalize(prompt);
  return JAMAICAN_ARTIST_PROFILES.filter((profile) => profile.aliases.some((alias) => text.includes(normalize(alias)) || text.replace(/ /g, "").includes(normalize(alias).replace(/ /g, ""))));
}

export function detectJamaicanGenre(prompt: string) {
  const text = normalize(prompt);
  return JAMAICAN_GENRE_PROFILES.slice().sort((left, right) => right.genreName.length - left.genreName.length).find((profile) => text.includes(normalize(profile.genreName)))
    ?? (text.includes("trap dancehall") || text.includes("dancehall trap") ? JAMAICAN_GENRE_PROFILES[0] : null);
}

function blendArtists(profiles: JamaicanArtistProfile[]): JamaicanArtistProfile | null {
  if (!profiles.length) return null;
  const [first] = profiles;
  if (!first) return null;
  const average = (selector: (profile: JamaicanArtistProfile) => number) => Number((profiles.reduce((sum, profile) => sum + selector(profile), 0) / profiles.length).toFixed(3));
  const weightedMaps = (selector: (profile: JamaicanArtistProfile) => Record<string, number>) => Object.fromEntries(unique(profiles.flatMap((profile) => Object.keys(selector(profile)))).map((key) => [key, average((profile) => selector(profile)[key] ?? 0)]));
  return { ...first, artistId: profiles.map((profile) => profile.artistId).join("-x-"), artistName: profiles.map((profile) => profile.artistName).join(" x "), aliases: unique(profiles.flatMap((profile) => profile.aliases)), primaryGenres: unique(profiles.flatMap((profile) => profile.primaryGenres)), secondaryGenres: unique(profiles.flatMap((profile) => profile.secondaryGenres)), subgenres: unique(profiles.flatMap((profile) => profile.subgenres)), keyTendencies: unique(profiles.flatMap((profile) => profile.keyTendencies)), scaleTendencies: unique(profiles.flatMap((profile) => profile.scaleTendencies)), harmonicCharacteristics: unique(profiles.flatMap((profile) => profile.harmonicCharacteristics)), melodicCharacteristics: unique(profiles.flatMap((profile) => profile.melodicCharacteristics)), rhythmicCharacteristics: unique(profiles.flatMap((profile) => profile.rhythmicCharacteristics)), bassCharacteristics: unique(profiles.flatMap((profile) => profile.bassCharacteristics)), instrumentPreferences: unique(profiles.flatMap((profile) => profile.instrumentPreferences)), commonInstruments: unique(profiles.flatMap((profile) => profile.commonInstruments)), emotionalCharacteristics: unique(profiles.flatMap((profile) => profile.emotionalCharacteristics)), songStructureTendencies: unique(profiles.flatMap((profile) => profile.songStructureTendencies)), productionCharacteristics: unique(profiles.flatMap((profile) => profile.productionCharacteristics)), tempo: { min: Math.round(average((profile) => profile.tempo.min)), max: Math.round(average((profile) => profile.tempo.max)), preferred: Math.round(average((profile) => profile.tempo.preferred)) }, melodyDensity: average((profile) => profile.melodyDensity), noteDensity: average((profile) => profile.noteDensity), phraseLength: Math.round(average((profile) => profile.phraseLength)), motifRepetition: average((profile) => profile.motifRepetition), syncopation: average((profile) => profile.syncopation), rhythmicComplexity: average((profile) => profile.rhythmicComplexity), chordComplexity: average((profile) => profile.chordComplexity), energy: average((profile) => profile.energy), referencePackWeights: weightedMaps((profile) => profile.referencePackWeights), songs: [], confidenceScore: average((profile) => profile.confidenceScore) };
}

export function selectReferencePacks(profile: JamaicanArtistProfile | null, genreProfile: JamaicanGenreProfile | null, prompt: string, random = Math.random) {
  const weights = new Map<string, number>();
  for (const [pack, weight] of Object.entries(profile?.referencePackWeights ?? {})) weights.set(pack, weight);
  for (const [pack, weight] of Object.entries(genreProfile?.referencePackWeights ?? {})) weights.set(pack, (weights.get(pack) ?? 0) + weight);
  const lower = prompt.toLowerCase();
  const instrumentBoosts: Array<[RegExp, string[]]> = [[/spanish|nylon|guitar/, ["Spanish Guitar MIDI Pack", "Emotional Guitar MIDI", "Afrobeat Guitar"]], [/piano|keys/, ["Dark Piano", "Trap Emotional Piano", "Drill Piano MIDI"]], [/808|bass/, ["808 MIDI", "Trap 808 MIDI"]]];
  for (const [pattern, packs] of instrumentBoosts) if (pattern.test(lower)) packs.forEach((pack) => weights.set(pack, (weights.get(pack) ?? 0) + 0.65));
  const pool = [...weights.entries()].filter(([, weight]) => weight > 0).sort((left, right) => right[1] - left[1]);
  const selected: Array<{ pack: string; weight: number }> = [];
  const explicitPacks = instrumentBoosts.flatMap(([pattern, packs]) => pattern.test(lower) ? packs : []).filter((pack, index, values) => values.indexOf(pack) === index && weights.has(pack));
  for (const pack of explicitPacks) {
    const weight = weights.get(pack) ?? 0;
    selected.push({ pack, weight: Number(weight.toFixed(3)) });
    const index = pool.findIndex(([candidate]) => candidate === pack);
    if (index >= 0) pool.splice(index, 1);
    if (selected.length === 5) break;
  }
  while (pool.length && selected.length < 5) {
    const total = pool.reduce((sum, [, weight]) => sum + weight, 0);
    let target = random() * total;
    const index = pool.findIndex(([, weight]) => (target -= weight) <= 0);
    const [pack, weight] = pool.splice(index < 0 ? 0 : index, 1)[0]!;
    selected.push({ pack, weight: Number(weight.toFixed(3)) });
  }
  return selected;
}

export function buildJamaicanGenerationContext(prompt: string, preferences: Omit<JamaicanGenerationContext["userPreferences"], "prompt"> = {}): JamaicanGenerationContext {
  const artists = detectJamaicanArtists(prompt);
  const profile = blendArtists(artists);
  const genreProfile = detectJamaicanGenre(prompt) ?? JAMAICAN_GENRE_PROFILES.find((candidate) => profile?.primaryGenres.includes(candidate.genreName)) ?? null;
  const instrument = preferences.instrument ?? (prompt.match(/spanish|nylon|guitar|piano|keys|bell|808|bass|pluck|pad/i)?.[0] ?? undefined);
  const instrumentProfile = instrument ? { name: instrument, weight: 1 } : null;
  const { songs: _songs, ...profileWithoutSongs } = profile ?? {};
  return { artistProfile: profile ? profileWithoutSongs : null, genreProfile, instrumentProfile, userPreferences: { prompt, ...preferences }, referenceFeatures: selectReferencePacks(profile, genreProfile, prompt), generationConstraints: { originalComposition: true, noLyrics: true, noKnownSongMelody: true, explicitUserDirectionWins: true as const, influenceWeights: { artist: 0.45, genre: 0.3, instrument: 0.15, reference: 0.1 } } };
}

export function aggregateArtistStyle(songs: AnalyzedSongStyle[]): AggregatedArtistStyle {
  const valid = songs.filter((song) => song.confidence >= 0 && (song.tempo !== null || song.melodyDensity !== undefined || song.harmonicDensity !== undefined || song.rhythmicDensity !== undefined));
  const average = (selector: (song: AnalyzedSongStyle) => number | null | undefined) => {
    const values = valid.map(selector).filter((value): value is number => typeof value === "number" && Number.isFinite(value));
    return values.length ? Number((values.reduce((sum, value) => sum + value, 0) / values.length).toFixed(3)) : null;
  };
  const tempos = valid.map((song) => song.tempo).filter((tempo): tempo is number => typeof tempo === "number" && Number.isFinite(tempo));
  const frequencies: Record<string, number> = {};
  const instrumentCounts: Record<string, number> = {};
  for (const song of valid) {
    for (const instrument of song.instruments ?? []) instrumentCounts[instrument] = (instrumentCounts[instrument] ?? 0) + 1;
    if (song.register) frequencies[song.register] = (frequencies[song.register] ?? 0) + 1;
  }
  const instrumentWeights = Object.fromEntries(Object.entries(instrumentCounts).map(([instrument, count]) => [instrument, Number((count / Math.max(1, valid.length)).toFixed(3))]));
  return {
    songCount: valid.length,
    tempo: { min: tempos.length ? Math.min(...tempos) : null, max: tempos.length ? Math.max(...tempos) : null, preferred: average((song) => song.tempo) },
    averages: { melodyDensity: average((song) => song.melodyDensity), harmonicDensity: average((song) => song.harmonicDensity), rhythmicDensity: average((song) => song.rhythmicDensity), syncopation: average((song) => song.syncopation), motifRepetition: average((song) => song.motifRepetition), phraseLength: average((song) => song.phraseLength), energy: average((song) => song.energy) },
    frequencies,
    instrumentWeights,
    confidence: average((song) => song.confidence) ?? 0,
  };
}